using TMPro;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
namespace CountToZero
{
 public sealed class CampaignExpansionUI:MonoBehaviour
 {
  [SerializeField] Sprite[] comic;
  [SerializeField] TextAsset credits;
  [SerializeField] Sprite panelSprite;
  readonly System.Collections.Generic.List<(Selectable control,Navigation navigation)> blocked=new();GameObject previousSelection;
  GameObject modal;Image frame;CampaignScreen screen;
  Transform canvas;
  TMP_FontAsset font;
  public static RectTransform Rect(string name,Transform parent,Vector2 position,Vector2 size){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=r.pivot=Vector2.one*.5f;r.anchoredPosition=position;r.sizeDelta=size;return r;}
  TMP_Text Text(Transform parent,string text,Vector2 pos,Vector2 size,int fontSize){var t=Rect("Text",parent,pos,size).gameObject.AddComponent<TextMeshProUGUI>();t.font=font;t.text=text;t.fontSize=fontSize;t.alignment=TextAlignmentOptions.Center;t.color=Color.white;t.raycastTarget=false;return t;}
  Button Button(Transform parent,string label,Vector2 pos,Vector2 size,UnityEngine.Events.UnityAction action){var r=Rect(label,parent,pos,size);var image=r.gameObject.AddComponent<Image>();image.sprite=panelSprite;image.type=Image.Type.Sliced;image.color=new Color(.2f,.45f,.65f,1);var b=r.gameObject.AddComponent<Button>();b.targetGraphic=image;r.gameObject.AddComponent<Outline>();r.gameObject.AddComponent<UIButtonFeedback>();var labelText=Text(r,label,Vector2.zero,size-Vector2.one*8,30);labelText.fontStyle=FontStyles.Bold;labelText.enableAutoSizing=true;labelText.fontSizeMin=20;labelText.fontSizeMax=30;b.onClick.AddListener(action);return b;}
  void Start(){screen=GetComponent<CampaignScreen>();var texts=FindObjectsByType<TextMeshProUGUI>(FindObjectsInactive.Include,FindObjectsSortMode.None);font=texts.Length>0?texts[0].font:TMP_Settings.defaultFontAsset;foreach(var c in FindObjectsByType<Canvas>(FindObjectsSortMode.None))if(c.renderMode!=RenderMode.WorldSpace){canvas=c.transform;break;}
   if(screen!=null){if(screen.Page==CampaignPage.Story||screen.Page==CampaignPage.StoryEnd)frame=StoryPageLayout.Arrange(screen);
    if(screen.Page==CampaignPage.Title && GetComponent<TitleMenuView>()==null)Button(canvas,"OPTIONS",new Vector2(0,-270),new Vector2(300,52),ShowOptions);
   }else {var options=FindFirstObjectByType<OptionsController>();if(options!=null){Button(options.PanelTransform,"CREDITS",new Vector2(260,-235),new Vector2(180,48),ShowCredits);}}
  }
  void Update(){if(frame!=null&&comic.Length>0)frame.sprite=comic[Mathf.Min(comic.Length-1,screen.Page==CampaignPage.StoryEnd?3:Mathf.Clamp(screen.StoryLine,0,2))];}
  void CloseModal(){if(modal!=null)Destroy(modal);modal=null;foreach(var item in blocked)if(item.control!=null){item.control.interactable=true;item.control.navigation=item.navigation;}blocked.Clear();if(previousSelection!=null)EventSystem.current?.SetSelectedGameObject(previousSelection);}
  Transform Modal(string title){if(modal==null){previousSelection=EventSystem.current!=null?EventSystem.current.currentSelectedGameObject:null;foreach(var control in FindObjectsByType<Selectable>(FindObjectsSortMode.None))if(control.IsInteractable()){blocked.Add((control,control.navigation));control.interactable=false;control.navigation=new Navigation{mode=Navigation.Mode.None};}}else Destroy(modal);var r=Rect(title,canvas,Vector2.zero,new Vector2(1120,640));modal=r.gameObject;var image=modal.AddComponent<Image>();image.sprite=panelSprite;image.type=Image.Type.Sliced;image.color=new Color(.3f,.5f,.7f,1);var backing=Rect("Opaque modal background",r,Vector2.zero,new Vector2(1100,620)).gameObject.AddComponent<Image>();backing.color=new Color(.015f,.025f,.045f,1);Text(r,title,new Vector2(0,265),new Vector2(1000,55),44);var close=Button(r,"BACK",new Vector2(0,-265),new Vector2(220,50),CloseModal);EventSystem.current?.SetSelectedGameObject(close.gameObject);return r;}
  public void ChooseDifficulty(){if(TryGetComponent<TitleMenuView>(out var titleView)){titleView.ShowDifficulty();return;}var r=Modal("SELECT DIFFICULTY");string[] names={"EASY","NORMAL","HARD"};string[] desc={"Gentler bullet speed","Original challenge","Faster attacks"};for(int i=0;i<3;i++){int d=i;var b=Button(r,names[i],new Vector2((i-1)*320,40),new Vector2(280,75),()=>screen.StartDifficulty(d));Text(r,desc[i],new Vector2((i-1)*320,-50),new Vector2(290,80),32);if(i==1)EventSystem.current?.SetSelectedGameObject(b.gameObject);}}
  void Volume(Transform parent,string name,float y,float value,UnityEngine.Events.UnityAction<float> change){Text(parent,name,new Vector2(-330,y),new Vector2(250,50),30);var r=Rect(name,parent,new Vector2(120,y),new Vector2(500,30));r.gameObject.AddComponent<Image>().color=new Color(.15f,.2f,.3f);var slider=r.gameObject.AddComponent<Slider>();var fill=Rect("Fill",r,Vector2.zero,new Vector2(500,30));fill.gameObject.AddComponent<Image>().color=Color.cyan;fill.anchorMin=Vector2.zero;fill.anchorMax=Vector2.one;fill.offsetMin=fill.offsetMax=Vector2.zero;slider.fillRect=fill;var handle=Rect("Handle",r,Vector2.zero,new Vector2(25,45));var hi=handle.gameObject.AddComponent<Image>();hi.color=Color.white;slider.handleRect=handle;slider.targetGraphic=hi;slider.SetValueWithoutNotify(value);slider.onValueChanged.AddListener(change);slider.onValueChanged.AddListener(_=>PlayerPrefs.Save());}
  public void ShowOptions(){if(TryGetComponent<TitleMenuView>(out var titleView)){titleView.ShowOptions();return;}var r=Modal("OPTIONS / AUDIO");Volume(r,"BGM",100,GameAudio.MusicVolume,GameAudio.SetMusic);Volume(r,"SFX",0,GameAudio.EffectsVolume,v=>{GameAudio.SetEffects(v);GameAudio.Play(SoundCue.UIClick);});Button(r,"CREDITS",new Vector2(0,-120),new Vector2(280,55),ShowCredits);}
  public void ShowCredits(){if(TryGetComponent<TitleMenuView>(out var titleView)){titleView.ShowCredits();return;}var r=Modal("ASSET CREDITS");var viewport=Rect("Credits viewport",r,new Vector2(0,0),new Vector2(1000,430));viewport.gameObject.AddComponent<RectMask2D>();viewport.gameObject.AddComponent<Image>().color=new Color(0,0,0,.01f);var scroll=viewport.gameObject.AddComponent<ScrollRect>();scroll.horizontal=false;scroll.viewport=viewport;var t=Text(viewport,credits!=null?credits.text:"Credits unavailable",Vector2.zero,new Vector2(950,850),25);t.alignment=TextAlignmentOptions.TopLeft;t.rectTransform.anchorMin=t.rectTransform.anchorMax=t.rectTransform.pivot=new Vector2(.5f,1);t.rectTransform.anchoredPosition=Vector2.zero;t.rectTransform.sizeDelta=new Vector2(950,Mathf.Max(850,t.GetPreferredValues().y+30));scroll.content=t.rectTransform;scroll.movementType=ScrollRect.MovementType.Clamped;}
 }
}
